sys_script_include.script:
var PlumbHub_ClientCollable = Class.create();
PlumbHub_ClientCollable.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	getPrice:function(){
		var priceFieldID =	this.getParameter('sysparm_price');
		var gr = new GlideRecord('x_1662477_plumbhub_products');
		gr.addQuery('sys_id', priceFieldID);
		if(gr.next()){
			gr.u_price;
		}
	},

    type: 'PlumbHub_ClientCollable'
});
